import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateSoftEnum{EnumType: "kits", Options: []string{"alpha", "beta"}, ActionType: packet.SoftEnumActionRemove}
REMOVE = bytes.fromhex("046b6974730205616c706861046265746101")

# generated by gophertunnel b8bd735:
# &packet.UpdateSoftEnum{EnumType: "kits", Options: nil, ActionType: packet.SoftEnumActionSet}
EMPTY = bytes.fromhex("046b6974730002")

# generated by gophertunnel b8bd735:
# &packet.UpdateSoftEnum{EnumType: "kits", Options: slices.Repeat([]string{"v"}, 200),
#   ActionType: packet.SoftEnumActionAdd}
TWO_HUNDRED_VALUES = bytes.fromhex("046b697473c801") + bytes.fromhex("0176") * 200 + bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.UpdateSoftEnumPacket(enum_name="kits", values=["alpha", "beta"], type=v2225.SoftEnumUpdateType.REMOVE),
        REMOVE,
        id="remove",
    ),
    pytest.param(
        v2225.UpdateSoftEnumPacket(enum_name="kits", values=[], type=v2225.SoftEnumUpdateType.REPLACE),
        EMPTY,
        id="empty-values-are-a-zero-count-the-update-type-follows",
    ),
    pytest.param(
        v2225.UpdateSoftEnumPacket(enum_name="kits", values=["v"] * 200, type=v2225.SoftEnumUpdateType.ADD),
        TWO_HUNDRED_VALUES,
        id="200-values-take-a-varint-count",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_update_soft_enum_is_packet_114(version):
    assert version.PACKETS[114] is version.UpdateSoftEnumPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_soft_enum_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_soft_enum_decodes_from_its_golden(packet, golden):
    assert v2225.UpdateSoftEnumPacket.from_bytes(golden) == packet
